script:
ALLOWED_TRANSITIONS = {
    "C0":          {"C1", "C2", "C6", "C7", "Archived", "Cold"},
    "C1":          {"C2", "C6", "C7"},
    "C2":          {"C2-Q", "C3", "C6", "C7"},
    "C2-Q":        {"C3", "C6", "C7"},
    "C3":          {"C4", "C5", "C8", "C6"},
    "C4":          {"C5", "C8"},
    "C5":          {"C8"},
    "C6":          set(),
    "C7":          {"C6", "C8"},
    "C8":          set(),
    "Cold":        {"C0", "Reactivated"},
    "Reactivated": {"C0", "C1", "C2", "C6", "Archived"},
    "Archived":    set(),
}

if not doc.is_new():
    old_doc = doc.get_doc_before_save()
    old_status = old_doc.status if old_doc else None
    new_status = doc.status
    if old_status and old_status != new_status:
        user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": frappe.session.user, "parenttype": "User"}, fields=["role"])}
        is_privileged = "Administrator" in user_roles or "Sales Manager" in user_roles
        if not is_privileged:
            if "B2F Team" in user_roles:
                if old_status != "C7" or new_status not in ("C6", "C8"):
                    frappe.throw(_("B2F Team can only update C7 leads to C6 or C8"))
            elif "Jr. Sales Executive" in user_roles:
                if new_status not in ("C1", "C2", "C6"):
                    frappe.throw(_("Spotters can only move leads to C1, C2, or C6"))
            elif "Calling Team" in user_roles:
                if old_status not in ("C0", "Cold", "Reactivated"):
                    frappe.throw(_("Calling Team can only manage leads at C0/Cold/Reactivated"))
                if new_status not in ("C1", "C2", "C6", "C7", "Archived", "C0"):
                    frappe.throw(_("Calling Team can only move leads to C1, C2, C6, C7, or Archived"))
            elif "Estimation Team" in user_roles:
                if old_status != "C2-Q" or new_status not in ("C3", "C6", "C7"):
                    frappe.throw(_("Estimation Team can only move C2-Q leads to C3, C6, or C7"))
            else:
                if doc.lead_owner != frappe.session.user:
                    frappe.throw(_("You can only change the status of leads you own"))

            # Task completion guards (bypassed by Sales Manager / Administrator)
            if old_status == "C2-Q" and new_status not in ("C6", "C7"):
                latest_quote_status = frappe.db.get_value(
                    "CRM Quote Request",
                    {"lead": doc.name},
                    "status",
                    order_by="creation desc",
                )
                if latest_quote_status != "Quote Received":
                    frappe.throw(
                        _("Cannot advance from C2-Q until the Estimation Team has set the Quote Request to 'Quote Received'."),
                        title=_("Quote Required"),
                    )

            if old_status == "C7":
                pending = frappe.db.get_value(
                    "CRM Task",
                    {
                        "reference_doctype": "CRM Lead",
                        "reference_docname": doc.name,
                        "task_type": "handle_fabricator_lead",
                        "status": ["not in", ["Done", "Canceled"]],
                    },
                    "name",
                )
                if pending:
                    frappe.throw(
                        _("Complete the 'Handle Fabricator Lead' task before updating the lead status."),
                        title=_("Task Incomplete"),
                    )

        if old_status in ALLOWED_TRANSITIONS:
            if new_status not in ALLOWED_TRANSITIONS.get(old_status, set()):
                frappe.throw(_(f"Cannot move from {old_status} to {new_status}"))

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None
new_status = doc.status

if old_doc is None and new_status == "C0":
    frappe.get_doc({
        "doctype": "CRM Task",
        "task_type": "call_lead",
        "title": f"Call Lead — {doc.lead_name or doc.name}",
        "status": "Todo",
        "priority": "Medium",
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.name,
        "description": f"New lead {doc.lead_name or doc.name} has arrived at C0. Make the initial call and log the disposition.",
    }).insert(ignore_permissions=True)

if old_status and old_status != new_status:
    if old_status in ("C0", "Cold") and new_status not in ("C0", "Cold"):
        frappe.enqueue(
            "crm.api.call_log.cancel_retry_log",
            lead_name=doc.name,
            permanent=True,
        )

    if new_status == "C1" and doc.email:
        frappe.enqueue(
            "crm.integrations.brevo.api.enroll_in_sequence",
            email=doc.email,
            lead_name=doc.name,
        )

    if new_status == "C2-Q":
        if not frappe.db.exists("CRM Quote Request", {"lead": doc.name, "status": "Pending"}):
            frappe.new_doc("CRM Quote Request").update({
                "lead": doc.name,
                "status": "Pending",
            }).insert(ignore_permissions=True)

        if not frappe.db.exists("CRM Task", {
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.name,
            "task_type": "upload_quote",
            "status": ["in", ["Todo", "In Progress"]],
        }):
            frappe.get_doc({
                "doctype": "CRM Task",
                "task_type": "upload_quote",
                "title": f"Upload Quote — {doc.lead_name or doc.name}",
                "status": "Todo",
                "priority": "High",
                "reference_doctype": "CRM Lead",
                "reference_docname": doc.name,
                "description": f"Upload the quotation for lead {doc.lead_name}. Click the Upload Quote button on the task to open the Quote Request, attach the quote file, enter Quote Value and Margin, then set status to Quote Received.",
            }).insert(ignore_permissions=True)

    if new_status == "C7":
        if not frappe.db.exists("CRM Task", {
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.name,
            "task_type": "handle_fabricator_lead",
            "status": ["in", ["Todo", "In Progress"]],
        }):
            frappe.get_doc({
                "doctype": "CRM Task",
                "task_type": "handle_fabricator_lead",
                "title": f"Handle Fabricator Lead — {doc.lead_name or doc.name}",
                "status": "Todo",
                "priority": "High",
                "reference_doctype": "CRM Lead",
                "reference_docname": doc.name,
                "description": f"Lead {doc.lead_name} has been routed to B2F (C7). Review the fabricator routing reason, coordinate with the partner fabricator, and update the lead to Won (C8) or Lost (C6).",
            }).insert(ignore_permissions=True)

if (
    doc.is_new()
    and doc.status == "No Answer"
    and doc.reference_doctype == "CRM Lead"
    and doc.reference_docname
):
    try:
        lead_status = frappe.db.get_value("CRM Lead", doc.reference_docname, "status")
        if lead_status in ("C0", "Cold"):
            frappe.enqueue(
                "crm.api.call_log.register_no_answer",
                lead_name=doc.reference_docname,
            )
    except Exception:
        frappe.log_error(frappe.get_traceback(), "No Answer Retry Trigger Failed")

if doc.mobile_no:
    existing = frappe.db.get_value(
        "CRM Lead",
        {"mobile_no": doc.mobile_no, "name": ["!=", doc.name]},
        ["name", "lead_name", "status"],
        as_dict=True,
    )
    if existing:
        frappe.throw(
            _(
                f"A lead with mobile {doc.mobile_no} already exists: "
                f"{existing.lead_name} ({existing.name}) — Stage: {existing.status}. "
                "Use the Reactivation flow if the lead is Cold or Archived."
            ),
            title=_("Duplicate Mobile Number"),
        )

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None

if old_status != doc.status and doc.status == "Quote Received":
    updates = {}
    if doc.quote_value:
        updates["custom_tentative_value"] = doc.quote_value
    if doc.quote_file:
        updates["custom_final_quote"] = doc.quote_file
    if updates:
        frappe.db.set_value("CRM Lead", doc.lead, updates)

    lead_owner = frappe.db.get_value("CRM Lead", doc.lead, "lead_owner")
    if lead_owner:
        frappe.get_doc({
            "doctype": "CRM Task",
            "title": f"Review & Share Quote — {doc.lead_name or doc.lead}",
            "status": "Todo",
            "priority": "High",
            "assigned_to": lead_owner,
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.lead,
            "description": f"Quote received for {doc.lead_name or doc.lead} (Value: {doc.quote_value}). Review the quotation and share it with the customer.",
        }).insert(ignore_permissions=True)

user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}

if "Sales Manager" in user_roles:
    conditions = ""
else:
    escaped_user = frappe.db.escape(user)
    base = f"""(
        `tabCRM Task`.assigned_to = {escaped_user}
        OR (
            `tabCRM Task`.reference_doctype = 'CRM Lead'
            AND EXISTS (
                SELECT 1 FROM `tabCRM Lead`
                WHERE `tabCRM Lead`.name = `tabCRM Task`.reference_docname
                AND `tabCRM Lead`.lead_owner = {escaped_user}
            )
        )
    )"""

    pool_clause = None
    if "Estimation Team" in user_roles:
        pool_clause = "(`tabCRM Task`.assigned_to IS NULL OR `tabCRM Task`.assigned_to = '') AND `tabCRM Task`.task_type = 'upload_quote'"
    elif "Calling Team" in user_roles:
        pool_clause = "(`tabCRM Task`.assigned_to IS NULL OR `tabCRM Task`.assigned_to = '') AND `tabCRM Task`.task_type = 'call_lead'"
    elif "B2F Team" in user_roles:
        pool_clause = "(`tabCRM Task`.assigned_to IS NULL OR `tabCRM Task`.assigned_to = '') AND `tabCRM Task`.task_type = 'handle_fabricator_lead'"

    if pool_clause:
        conditions = f"({base} OR ({pool_clause}))"
    else:
        conditions = base

POOL_TASK_ROLES = {
    "call_lead": "Calling Team",
    "upload_quote": "Estimation Team",
    "handle_fabricator_lead": "B2F Team",
}

user = frappe.session.user
if user == "Administrator" or doc.flags.get("ignore_permissions"):
    pass
else:
    user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}
    if not ("System Manager" in user_roles or "Sales Manager" in user_roles):
        task_type = doc.task_type or ""
        if task_type in POOL_TASK_ROLES:
            required_role = POOL_TASK_ROLES[task_type]
            if required_role not in user_roles and doc.assigned_to != user:
                frappe.throw(
                    _(f"Only {required_role} members can update this task."),
                    frappe.PermissionError,
                    title=_("Not Permitted"),
                )
        elif doc.assigned_to and doc.assigned_to != user:
            lead_owner = None
            if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
                lead_owner = frappe.db.get_value("CRM Lead", doc.reference_docname, "lead_owner")
            if lead_owner != user:
                frappe.throw(
                    _("You can only update tasks assigned to you or for leads you own."),
                    frappe.PermissionError,
                    title=_("Not Permitted"),
                )

POOL_TASK_ROLES = {
    "call_lead": "Calling Team",
    "upload_quote": "Estimation Team",
    "handle_fabricator_lead": "B2F Team",
}

user = frappe.session.user
if user == "Administrator" or doc.flags.get("ignore_permissions"):
    pass
else:
    user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}
    if not ("System Manager" in user_roles or "Sales Manager" in user_roles):
        if (doc.task_type or "") in POOL_TASK_ROLES:
            frappe.throw(
                _("Pool tasks cannot be deleted. Mark the task as Done or Canceled instead."),
                frappe.PermissionError,
                title=_("Not Permitted"),
            )
        elif doc.assigned_to and doc.assigned_to != user:
            lead_owner = None
            if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
                lead_owner = frappe.db.get_value("CRM Lead", doc.reference_docname, "lead_owner")
            if lead_owner != user:
                frappe.throw(
                    _("You can only delete tasks assigned to you or for leads you own."),
                    frappe.PermissionError,
                    title=_("Not Permitted"),
                )
